def _eval_expr(expr: str, row: dict[str, Any]) -> Any:
    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError as exc:
        raise ETLError("BAD_EXPR", f"invalid expression: {exc.msg}", "") from exc

