        return 0
    except json.JSONDecodeError as exc:
        emit(ETLError("SCHEMA_VALIDATION_FAILED", f"invalid JSON input: {exc.msg}", "").as_dict())
        return 1
    except ETLError as exc:
        emit(exc.as_dict())
        return 1


