    return value


def clean_text(value: Any, path: str, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ETLError("SCHEMA_VALIDATION_FAILED", f"{label} must be a non-empty string", path)
    return value.strip()


