    rows = [dict(row) for row in dataset]
    for i, step in enumerate(steps):
        op = step["op"]
        path = f"pipeline.steps[{i}]"
        if op == "select":
            selected = []
            for row in rows:
                item = {}
                for j, column in enumerate(step["columns"]):
